    output reg  [3:0] phase_out
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            phase_out <= 4'b0001;
        end else if (en) begin
            if (dir) begin
                case (phase_out)
                    4'b0001: phase_out <= 4'b0010;
                    4'b0010: phase_out <= 4'b0100;
                    4'b0100: phase_out <= 4'b1000;
                    4'b1000: phase_out <= 4'b0001;
                    default: phase_out <= 4'b0001;
                endcase
            end else begin
                case (phase_out)
                    4'b1000: phase_out <= 4'b0100;
                    4'b0100: phase_out <= 4'b0010;
                    4'b0010: phase_out <= 4'b0001;
                    4'b0001: phase_out <= 4'b1000;
                    default: phase_out <= 4'b0001;
                endcase
            end
        end
    end

endmodule
